import torch
import torch.nn as nn
class LoRALayer(nn.Module):
    def __init__(self, r, d_in, d_out):
        super().__init__()
        self.A = nn.Parameter(torch.randn(r, d_in))
        self.B = nn.Parameter(torch.zeros(d_out, r))
    def forward(self, x):
        return x + x @ self.B.T @ self.A
